#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    string row, col;
    cin >> row >> col;

    auto reachable = [&](bool reverse) {
        vector<vector<bool>> visited(n, vector<bool>(m, false));
        stack<pair<int, int>> st;
        st.push({0, 0});
        visited[0][0] = true;
        int count = 0;

        while (!st.empty()) {
            auto [r, c] = st.top();
            st.pop();
            ++count;

            int nc = c + ((row[r] == '>') ^ reverse ? 1 : -1);
            if (nc >= 0 && nc < m && !visited[r][nc]) {
                visited[r][nc] = true;
                st.push({r, nc});
            }

            int nr = r + ((col[c] == 'v') ^ reverse ? 1 : -1);
            if (nr >= 0 && nr < n && !visited[nr][c]) {
                visited[nr][c] = true;
                st.push({nr, c});
            }
        }

        return count == n * m;
    };

    cout << (reachable(false) && reachable(true) ? "YES" : "NO");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    string row, col;
    cin >> n >> m >> row >> col;

    int total = n * m;
    vector<vector<int>> graph(total), reverseGraph(total);

    auto addEdge = [&](int from, int to) {
        graph[from].push_back(to);
        reverseGraph[to].push_back(from);
    };

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int current = i * m + j;

            int nextJ = j + (row[i] == '>' ? 1 : -1);
            if (nextJ >= 0 && nextJ < m)
                addEdge(current, i * m + nextJ);

            int nextI = i + (col[j] == 'v' ? 1 : -1);
            if (nextI >= 0 && nextI < n)
                addEdge(current, nextI * m + j);
        }
    }

    auto reachable = [&](const vector<vector<int>>& g) {
        vector<bool> visited(total, false);
        queue<int> q;
        q.push(0);
        visited[0] = true;
        int count = 0;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            ++count;

            for (int v : g[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
        return count == total;
    };

    cout << (reachable(graph) && reachable(reverseGraph) ? "YES" : "NO");
    return 0;
}

