    int n, m;
    string row, col;
    cin >> n >> m >> row >> col;

    auto reachable = [&](bool reversed) {
        vector<vector<bool>> visited(n, vector<bool>(m, false));
        queue<pair<int, int>> q;
        q.push({0, 0});
        visited[0][0] = true;
        int count = 0;

        while (!q.empty()) {
            auto [r, c] = q.front();
            q.pop();
            ++count;

            vector<pair<int, int>> next;
            if (!reversed) {
                next.push_back({r, c + (row[r] == '>' ? 1 : -1)});
                next.push_back({r + (col[c] == 'v' ? 1 : -1), c});
            } else {
                next.push_back({r, c + (row[r] == '>' ? -1 : 1)});
                next.push_back({r + (col[c] == 'v' ? -1 : 1), c});
            }

            for (auto [nr, nc] : next) {
                if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                    !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    q.push({nr, nc});
                }
            }
        }

        return count == n * m;
    };

    cout << (reachable(false) && reachable(true) ? "YES" : "NO");
    return 0;
}

